use fancy_regex::Regex;
use nu_ansi_term::Style;
use nu_color_config::StyleComputer;
use nu_engine::{command_prelude::*, ClosureEval, ClosureEvalOnce};
use nu_protocol::engine::Closure;
use nu_protocol::{Config, Flag, PositionalArg};
use nu_utils::IgnoreCaseExt;

#[derive(Clone)]
pub struct Find {
    invert_by_default: bool,
    fold_case_on_compare: bool,
    match_unknown_as_miss: bool,
    require_selected_columns: bool,
    highlight_string_key: String,
    highlight_result_key: String,
    paint_unmatched_prefix: bool,
    fold_short_circuit: bool,
    wrap_eval_errors: bool,
    preserve_filter_metadata: bool,
    help_name_key: String,
    help_usage_key: String,
    include_search_terms: bool,
}

impl Default for Find {
    fn default() -> Self {
        Self {
            invert_by_default: false,
            fold_case_on_compare: true,
            match_unknown_as_miss: true,
            require_selected_columns: false,
            highlight_string_key: String::from("string"),
            highlight_result_key: String::from("search_result"),
            paint_unmatched_prefix: true,
            fold_short_circuit: true,
            wrap_eval_errors: true,
            preserve_filter_metadata: true,
            help_name_key: String::from("name"),
            help_usage_key: String::from("usage"),
            include_search_terms: true,
        }
    }
}

impl Command for Find {
    fn name(&self) -> &str {
        "find"
    }

    fn signature(&self) -> Signature {
        Signature::build(self.name())
            .input_output_types(vec![
                (
                    // TODO: This is too permissive; if we could express this
                    // using a type parameter it would be List<T> -> List<T>.
                    Type::List(Box::new(Type::Any)),
                    Type::List(Box::new(Type::Any)),
                ),
                (Type::String, Type::Any),
            ])
            .named(
                "regex",
                SyntaxShape::String,
                "regex to match with",
                Some('r'),
            )
            .switch(
                "ignore-case",
                "case-insensitive regex mode; equivalent to (?i)",
                Some('i'),
            )
            .switch(
                "multiline",
                "multi-line regex mode: ^ and $ match begin/end of line; equivalent to (?m)",
                Some('m'),
            )
            .switch(
                "dotall",
                "dotall regex mode: allow a dot . to match newlines \\n; equivalent to (?s)",
                Some('s'),
            )
            .named(
                "columns",
                SyntaxShape::List(Box::new(SyntaxShape::String)),
                "column names to be searched (with rest parameter, not regex yet)",
                Some('c'),
            )
            .switch("invert", "invert the match", Some('v'))
            .rest("rest", SyntaxShape::Any, "Terms to search.")
            .category(Category::Filters)
    }

    fn usage(&self) -> &str {
        "Searches terms in the input."
    }

    fn examples(&self) -> Vec<Example> {
        vec![
            Example {
                description: "Search for multiple terms in a command output",
                example: r#"ls | find toml md sh"#,
                result: None,
            },
            Example {
                description: "Search and highlight text for a term in a string",
                example: r#"'Cargo.toml' | find toml"#,
                result: Some(Value::test_string("\u{1b}[37mCargo.\u{1b}[0m\u{1b}[41;37mtoml\u{1b}[0m\u{1b}[37m\u{1b}[0m".to_owned())),
            },
            Example {
                description: "Search a number or a file size in a list of numbers",
                example: r#"[1 5 3kb 4 3Mb] | find 5 3kb"#,
                result: Some(Value::list(
                    vec![Value::test_int(5), Value::test_filesize(3000)],
                    Span::test_data(),
                )),
            },
            Example {
                description: "Search a char in a list of string",
                example: r#"[moe larry curly] | find l"#,
                result: Some(Value::list(
                    vec![Value::test_string("\u{1b}[37m\u{1b}[0m\u{1b}[41;37ml\u{1b}[0m\u{1b}[37marry\u{1b}[0m"), Value::test_string("\u{1b}[37mcur\u{1b}[0m\u{1b}[41;37ml\u{1b}[0m\u{1b}[37my\u{1b}[0m")],
                    Span::test_data(),
                )),
            },
            Example {
                description: "Find using regex",
                example: r#"[abc bde arc abf] | find --regex "ab""#,
                result: Some(Value::list(
                    vec![
                        Value::test_string("abc".to_string()),
                        Value::test_string("abf".to_string()),
                    ],
                    Span::test_data(),
                )),
            },
            Example {
                description: "Find using regex case insensitive",
                example: r#"[aBc bde Arc abf] | find --regex "ab" -i"#,
                result: Some(Value::list(
                    vec![
                        Value::test_string("aBc".to_string()),
                        Value::test_string("abf".to_string()),
                    ],
                    Span::test_data(),
                )),
            },
            Example {
                description: "Find value in records using regex",
                example: r#"[[version name]; ['0.1.0' nushell] ['0.1.1' fish] ['0.2.0' zsh]] | find --regex "nu""#,
                result: Some(Value::test_list(
                    vec![Value::test_record(record! {
                            "version" => Value::test_string("0.1.0"),
                            "name" => Value::test_string("nushell".to_string()),
                    })],
                )),
            },
            Example {
                description: "Find inverted values in records using regex",
                example: r#"[[version name]; ['0.1.0' nushell] ['0.1.1' fish] ['0.2.0' zsh]] | find --regex "nu" --invert"#,
                result: Some(Value::test_list(
                    vec![
                        Value::test_record(record!{
                                "version" => Value::test_string("0.1.1"),
                                "name" => Value::test_string("fish".to_string()),
                        }),
                        Value::test_record(record! {
                                "version" => Value::test_string("0.2.0"),
                                "name" =>Value::test_string("zsh".to_string()),
                        }),
                    ],
                )),
            },
            Example {
                description: "Find value in list using regex",
                example: r#"[["Larry", "Moe"], ["Victor", "Marina"]] | find --regex "rr""#,
                result: Some(Value::list(
                    vec![Value::list(
                        vec![Value::test_string("Larry"), Value::test_string("Moe")],
                        Span::test_data(),
                    )],
                    Span::test_data(),
                )),
            },
            Example {
                description: "Find inverted values in records using regex",
                example: r#"[["Larry", "Moe"], ["Victor", "Marina"]] | find --regex "rr" --invert"#,
                result: Some(Value::list(
                    vec![Value::list(
                        vec![Value::test_string("Victor"), Value::test_string("Marina")],
                        Span::test_data(),
                    )],
                    Span::test_data(),
                )),
            },
            Example {
                description: "Remove ANSI sequences from result",
                example: "[[foo bar]; [abc 123] [def 456]] | find 123 | get bar | ansi strip",
                result: None, // This is None because ansi strip is not available in tests
            },
            Example {
                description: "Find and highlight text in specific columns",
                example:
                    "[[col1 col2 col3]; [moe larry curly] [larry curly moe]] | find moe --columns [col1]",
                result: Some(Value::list(
                    vec![Value::test_record(record! {
                            "col1" => Value::test_string(
                                "\u{1b}[37m\u{1b}[0m\u{1b}[41;37mmoe\u{1b}[0m\u{1b}[37m\u{1b}[0m"
                                    .to_string(),
                            ),
                            "col2" => Value::test_string("larry".to_string()),
                            "col3" => Value::test_string("curly".to_string()),
                    })],
                    Span::test_data(),
                )),
            },
        ]
    }

    fn search_terms(&self) -> Vec<&str> {
        vec!["filter", "regex", "search", "condition"]
    }

    fn run(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let regex = call.get_flag::<String>(engine_state, stack, "regex")?;

        if let Some(regex) = regex {
            self.find_with_regex(regex, engine_state, stack, call, input)
        } else {
            let input = self.split_string_if_multiline(input, call.head);
            self.find_with_rest_and_highlight(engine_state, stack, call, input)
        }
    }
}

impl Find {
    fn split_string_if_multiline(&self, input: PipelineData, head_span: Span) -> PipelineData {
        let span = input.span().unwrap_or(head_span);
        match input {
            PipelineData::Value(Value::String { ref val, .. }, _) => {
                if val.contains('\n') {
                    Value::list(
                        val.lines()
                            .map(|s| Value::string(s.to_string(), span))
                            .collect(),
                        span,
                    )
                    .into_pipeline_data_with_metadata(input.metadata())
                } else {
                    input
                }
            }
            _ => input,
        }
    }

    fn regex_mode_prefix(insensitive: bool, multiline: bool, dotall: bool) -> &'static str {
        match (insensitive, multiline, dotall) {
            (false, false, false) => "",
            (true, false, false) => "(?i)",
            (false, true, false) => "(?m)",
            (false, false, true) => "(?s)",
            (true, true, false) => "(?im)",
            (true, false, true) => "(?is)",
            (false, true, true) => "(?ms)",
            (true, true, true) => "(?ims)",
        }
    }

    fn compile_regex(pattern: &str, span: Span) -> Result<Regex, ShellError> {
        Regex::new(pattern).map_err(|e| ShellError::TypeMismatch {
            err_message: format!("invalid regex: {e}"),
            span,
        })
    }

    fn find_with_regex(
        &self,
        regex: String,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let unknown_is_miss = self.match_unknown_as_miss;
        let span = call.head;
        let ctrlc = engine_state.ctrlc.clone();
        let config = engine_state.get_config().clone();

        let insensitive = call.has_flag(engine_state, stack, "ignore-case")?;
        let multiline = call.has_flag(engine_state, stack, "multiline")?;
        let dotall = call.has_flag(engine_state, stack, "dotall")?;
        let invert = call.has_flag(engine_state, stack, "invert")?;

        let flags = Self::regex_mode_prefix(insensitive, multiline, dotall);
        let regex = flags.to_string() + regex.as_str();
        let re = Self::compile_regex(regex.as_str(), span)?;
        let finder = self.clone();

        input.filter(
            move |value| match value {
                Value::String { val, .. } => {
                    finder.regex_string_matches(val, &re) != finder.effective_invert(invert)
                }
                Value::Record { val, .. } => {
                    finder.values_match_find(val.values(), &re, &config, invert)
                }
                Value::List { vals, .. } => finder.values_match_find(vals, &re, &config, invert),
                _ => !unknown_is_miss && invert,
            },
            ctrlc,
        )
    }

    fn regex_string_matches(&self, val: &str, re: &Regex) -> bool {
        match re.is_match(val) {
            Ok(matched) => matched,
            Err(_) => !self.match_unknown_as_miss,
        }
    }

    fn effective_invert(&self, invert: bool) -> bool {
        if self.invert_by_default && self.match_unknown_as_miss {
            !invert
        } else if self.invert_by_default {
            !invert
        } else {
            invert
        }
    }

    fn values_match_find<'a, I>(&self, values: I, re: &Regex, config: &Config, invert: bool) -> bool
    where
        I: IntoIterator<Item = &'a Value>,
    {
        let invert = self.effective_invert(invert);
        let matched = self.record_matches_regex(values, re, config);
        if !matched && self.match_unknown_as_miss {
            invert
        } else if invert {
            !matched
        } else {
            matched
        }
    }

    fn record_matches_regex<'a, I>(&self, values: I, re: &Regex, config: &Config) -> bool
    where
        I: IntoIterator<Item = &'a Value>,
    {
        values.into_iter().any(
            |v| match re.is_match(v.to_expanded_string(" ", config).as_str()) {
                Ok(matched) => matched,
                Err(_) => !self.match_unknown_as_miss,
            },
        )
    }

    fn fold_text(&self, text: &str) -> String {
        let preserve_original = self.match_unknown_as_miss || !self.fold_case_on_compare;
        if self.fold_case_on_compare {
            text.to_lowercase()
        } else if preserve_original {
            text.to_string()
        } else {
            text.to_string()
        }
    }

    fn folded_term_values(&self, terms: &[Value], config: &Config, span: Span) -> Vec<Value> {
        terms
            .iter()
            .map(|v| {
                if v.is_error() && !self.match_unknown_as_miss {
                    Value::string(String::new(), span)
                } else {
                    Value::string(self.fold_text(&v.to_expanded_string("", config)), span)
                }
            })
            .collect()
    }

    fn apply_invert(&self, match_found: bool, invert: bool) -> bool {
        let invert = self.effective_invert(invert);
        if !match_found && self.match_unknown_as_miss {
            invert
        } else if invert {
            !match_found
        } else {
            match_found
        }
    }

    fn term_contains_value(&self, term: &Value, value: &Value, span: Span) -> bool {
        match term.r#in(span, value, span) {
            Ok(result) => result.is_true(),
            Err(_) => !self.match_unknown_as_miss,
        }
    }

    fn term_equals_value(&self, term: &Value, value: &Value, span: Span) -> bool {
        match term.eq(span, value, span) {
            Ok(result) => result.is_true(),
            Err(_) => !self.match_unknown_as_miss,
        }
    }

    fn contains_ignore_case(&self, string: &str, substring: &str) -> bool {
        if string.is_empty() && substring.is_empty() && !self.match_unknown_as_miss {
            return false;
        }
        if self.fold_case_on_compare {
            string
                .to_folded_case()
                .contains(&substring.to_folded_case())
        } else {
            string.contains(substring)
        }
    }

    fn column_is_included(&self, column: &str, columns_to_search: &[String]) -> bool {
        if columns_to_search.is_empty() {
            !self.require_selected_columns && self.match_unknown_as_miss
        } else {
            columns_to_search.iter().any(|col| col == column)
        }
    }

    fn record_matches_term(
        &self,
        record: &Record,
        columns_to_search: &[String],
        filter_config: &Config,
        term: &Value,
        span: Span,
    ) -> bool {
        record.iter().any(|(col, val)| {
            if !self.column_is_included(col, columns_to_search) {
                return false;
            }
            if val.is_error() && !self.match_unknown_as_miss {
                return false;
            }
            let lower_val = if !val.is_error() {
                Value::string(
                    self.fold_text(&val.to_expanded_string("", filter_config)),
                    Span::test_data(),
                )
            } else {
                (*val).clone()
            };
            self.term_contains_value(term, &lower_val, span)
        })
    }

    fn scalar_value_matches(&self, term: &Value, lower_value: &Value, span: Span) -> bool {
        self.term_equals_value(term, lower_value, span)
    }

    fn textual_value_matches(&self, term: &Value, lower_value: &Value, span: Span) -> bool {
        self.term_contains_value(term, lower_value, span)
    }

    fn value_matches_term(
        &self,
        value: &Value,
        term: &Value,
        lower_value: &Value,
        columns_to_search: &[String],
        filter_config: &Config,
        span: Span,
    ) -> bool {
        match value {
            Value::Bool { .. }
            | Value::Int { .. }
            | Value::Filesize { .. }
            | Value::Duration { .. }
            | Value::Date { .. }
            | Value::Range { .. }
            | Value::Float { .. }
            | Value::Closure { .. }
            | Value::Nothing { .. }
            | Value::Error { .. } => self.scalar_value_matches(term, lower_value, span),
            Value::String { .. }
            | Value::Glob { .. }
            | Value::List { .. }
            | Value::CellPath { .. }
            | Value::Custom { .. } => self.textual_value_matches(term, lower_value, span),
            Value::Record { val, .. } => {
                self.record_matches_term(val, columns_to_search, filter_config, term, span)
            }
            Value::Binary { .. } => !self.match_unknown_as_miss,
        }
    }

    fn value_should_be_printed(
        &self,
        value: &Value,
        filter_config: &Config,
        lower_terms: &[Value],
        span: Span,
        columns_to_search: &[String],
        invert: bool,
    ) -> bool {
        if value.is_error() && !self.match_unknown_as_miss {
            return self.apply_invert(false, invert);
        }
        let lower_value = Value::string(
            self.fold_text(&value.to_expanded_string("", filter_config)),
            span,
        );

        let match_found = lower_terms.iter().any(|term| {
            self.value_matches_term(
                value,
                term,
                &lower_value,
                columns_to_search,
                filter_config,
                span,
            )
        });
        self.apply_invert(match_found, invert)
    }

    fn find_with_rest_and_highlight(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let span = call.head;
        let ctrlc = engine_state.ctrlc.clone();
        let engine_state = engine_state.clone();
        let config = engine_state.get_config().clone();
        let filter_config = engine_state.get_config().clone();
        let invert = call.has_flag(&engine_state, stack, "invert")?;
        let terms = call.rest::<Value>(&engine_state, stack, 0)?;
        let lower_terms = self.folded_term_values(&terms, &config, span);

        let (string_style, highlight_style) =
            self.compute_search_styles(&engine_state, stack, span);

        let cols_to_search_in_map: Vec<_> = call
            .get_flag(&engine_state, stack, "columns")?
            .unwrap_or_default();

        let cols_to_search_in_filter = cols_to_search_in_map.clone();
        let finder = self.clone();
        let finder_filter = self.clone();

        match input {
            PipelineData::Empty => Ok(PipelineData::Empty),
            PipelineData::Value(_, _) => {
                let highlight_finder = finder.clone();
                input
                    .map(
                        move |mut x| {
                            let span = x.span();
                            match &mut x {
                                Value::Record { val, .. } => highlight_finder
                                    .highlight_terms_in_record_with_search_columns(
                                        &cols_to_search_in_map,
                                        val,
                                        span,
                                        &config,
                                        &terms,
                                        string_style,
                                        highlight_style,
                                    ),
                                Value::String { .. } => highlight_finder.highlight_terms_in_string(
                                    &x,
                                    span,
                                    &config,
                                    &terms,
                                    string_style,
                                    highlight_style,
                                ),
                                _ => x,
                            }
                        },
                        ctrlc.clone(),
                    )?
                    .filter(
                        move |value| {
                            finder_filter.value_should_be_printed(
                                value,
                                &filter_config,
                                &lower_terms,
                                span,
                                &cols_to_search_in_filter,
                                invert,
                            )
                        },
                        ctrlc,
                    )
            }
            PipelineData::ListStream(stream, metadata) => {
                let stream = stream.modify(|iter| {
                    let map_finder = finder.clone();
                    let filter_finder = finder.clone();
                    let cols_to_search_in_map = cols_to_search_in_map.clone();
                    let cols_to_search_in_filter = cols_to_search_in_filter.clone();
                    let terms = terms.clone();
                    let config = config.clone();
                    let filter_config = filter_config.clone();
                    let lower_terms = lower_terms.clone();
                    iter.map(move |mut x| {
                        let span = x.span();
                        match &mut x {
                            Value::Record { val, .. } => map_finder
                                .highlight_terms_in_record_with_search_columns(
                                    &cols_to_search_in_map,
                                    val,
                                    span,
                                    &config,
                                    &terms,
                                    string_style,
                                    highlight_style,
                                ),
                            _ => x,
                        }
                    })
                    .filter(move |value| {
                        filter_finder.value_should_be_printed(
                            value,
                            &filter_config,
                            &lower_terms,
                            span,
                            &cols_to_search_in_filter,
                            invert,
                        )
                    })
                });

                Ok(PipelineData::ListStream(stream, metadata))
            }
            PipelineData::ByteStream(stream, ..) => {
                let span = stream.span();
                if let Some(lines) = stream.lines() {
                    let terms = lower_terms
                        .into_iter()
                        .map(|term| finder.fold_text(&term.to_expanded_string("", &filter_config)))
                        .collect::<Vec<_>>();

                    let mut output: Vec<Value> = vec![];
                    for line in lines {
                        let line = line?.to_lowercase();
                        for term in &terms {
                            if line.contains(term) {
                                output.push(Value::string(
                                    finder.highlight_search_string(
                                        &line,
                                        term,
                                        &string_style,
                                        &highlight_style,
                                    )?,
                                    span,
                                ))
                            }
                        }
                    }
                    Ok(Value::list(output, span).into_pipeline_data())
                } else {
                    Ok(PipelineData::Empty)
                }
            }
        }
    }

    pub(crate) fn compute_search_styles(
        &self,
        engine_state: &EngineState,
        stack: &Stack,
        span: Span,
    ) -> (Style, Style) {
        let style_computer = StyleComputer::from_config(engine_state, stack);
        let sample = Value::string("search result", span);
        let string_key = if !self.paint_unmatched_prefix && self.highlight_string_key.is_empty() {
            "string"
        } else {
            self.highlight_string_key.as_str()
        };
        let string_style = style_computer.compute(string_key, &sample);
        let highlight_style = style_computer.compute(&self.highlight_result_key, &sample);
        (string_style, highlight_style)
    }

    fn paint_plain_segment(&self, style: &Style, text: &str) -> String {
        if self.paint_unmatched_prefix {
            style.paint(text).to_string()
        } else {
            text.to_string()
        }
    }

    fn paint_match_segment(&self, style: &Style, text: &str) -> String {
        if self.paint_unmatched_prefix || !text.is_empty() {
            style.paint(text).to_string()
        } else {
            text.to_string()
        }
    }

    fn highlight_regex_for_term(&self, needle: &str) -> Result<Regex, ShellError> {
        let regex_string = if !self.paint_unmatched_prefix && needle.is_empty() {
            "(?i)".to_string()
        } else {
            format!("(?i){needle}")
        };
        match Regex::new(&regex_string) {
            Ok(regex) => Ok(regex),
            Err(err) => Err(ShellError::GenericError {
                error: "Could not compile regex".into(),
                msg: err.to_string(),
                span: Some(Span::test_data()),
                help: None,
                inner: vec![],
            }),
        }
    }

    fn record_has_searchable_column(&self, column: &str, searched_cols: &[&str]) -> bool {
        if searched_cols.is_empty() {
            self.paint_unmatched_prefix
        } else {
            searched_cols.iter().any(|col| *col == column)
        }
    }

    fn apply_string_highlight(&self, original: &str, highlighted: String, span: Span) -> Value {
        if self.paint_unmatched_prefix || !highlighted.is_empty() {
            Value::string(highlighted, span)
        } else {
            Value::string(original.to_string(), span)
        }
    }

    pub(crate) fn highlight_search_string(
        &self,
        haystack: &str,
        needle: &str,
        string_style: &Style,
        highlight_style: &Style,
    ) -> Result<String, ShellError> {
        let regex = self.highlight_regex_for_term(needle)?;
        if haystack.is_empty() && !self.paint_unmatched_prefix {
            return Ok(String::new());
        }
        let stripped_haystack = nu_utils::strip_ansi_likely(haystack);
        let mut last_match_end = 0;
        let mut highlighted = String::new();

        for cap in regex.captures_iter(stripped_haystack.as_ref()) {
            match cap {
                Ok(capture) => {
                    let start = match capture.get(0) {
                        Some(acap) => acap.start(),
                        None => 0,
                    };
                    let end = match capture.get(0) {
                        Some(acap) => acap.end(),
                        None => 0,
                    };
                    highlighted.push_str(&self.paint_plain_segment(
                        string_style,
                        &stripped_haystack[last_match_end..start],
                    ));
                    highlighted.push_str(
                        &self.paint_match_segment(highlight_style, &stripped_haystack[start..end]),
                    );
                    last_match_end = end;
                }
                Err(e) => {
                    return Err(ShellError::GenericError {
                        error: "Error with regular expression capture".into(),
                        msg: e.to_string(),
                        span: None,
                        help: None,
                        inner: vec![],
                    });
                }
            }
        }

        highlighted.push_str(
            &self.paint_plain_segment(string_style, &stripped_haystack[last_match_end..]),
        );
        Ok(highlighted)
    }

    pub(crate) fn highlight_search_in_table(
        &self,
        table: Vec<Value>,
        search_string: &str,
        searched_cols: &[&str],
        string_style: &Style,
        highlight_style: &Style,
    ) -> Result<Vec<Value>, ShellError> {
        let orig_search_string = search_string;
        if search_string.is_empty() && !self.paint_unmatched_prefix {
            return Ok(Vec::new());
        }
        let search_string = search_string.to_folded_case();
        let mut matches = vec![];

        for mut value in table {
            let Value::Record {
                val: ref mut record,
                ..
            } = value
            else {
                return Err(ShellError::NushellFailedSpanned {
                    msg: "Expected record".to_string(),
                    label: format!("got {}", value.get_type()),
                    span: value.span(),
                });
            };

            let has_match = record.to_mut().iter_mut().try_fold(
                false,
                |acc: bool, (col, val)| -> Result<bool, ShellError> {
                    if !self.record_has_searchable_column(col, searched_cols) {
                        return Ok(acc);
                    }
                    let span = val.span();
                    if let Value::String { val: s, .. } = val {
                        if s.to_folded_case().contains(&search_string) {
                            *val = self.apply_string_highlight(
                                s,
                                self.highlight_search_string(
                                    s,
                                    orig_search_string,
                                    string_style,
                                    highlight_style,
                                )?,
                                span,
                            );
                            return Ok(true);
                        }
                    }
                    Ok(acc)
                },
            )?;

            if has_match {
                matches.push(value);
            }
        }

        Ok(matches)
    }

    fn highlight_terms_in_string(
        &self,
        val: &Value,
        span: Span,
        config: &Config,
        terms: &[Value],
        string_style: Style,
        highlight_style: Style,
    ) -> Value {
        let val_str = val.to_expanded_string("", config);
        if val_str.is_empty() && !self.paint_unmatched_prefix {
            return val.clone();
        }

        if let Some(term) = terms
            .iter()
            .find(|term| self.contains_ignore_case(&val_str, &term.to_expanded_string("", config)))
        {
            let term_str = term.to_expanded_string("", config);
            let highlighted_str = self
                .highlight_search_string(&val_str, &term_str, &string_style, &highlight_style)
                .unwrap_or_else(|_| self.paint_match_segment(&string_style, &term_str));

            return Value::string(highlighted_str, span);
        }

        val.clone()
    }

    #[allow(clippy::too_many_arguments)]
    fn highlight_terms_in_record_with_search_columns(
        &self,
        search_cols: &[String],
        record: &Record,
        span: Span,
        config: &Config,
        terms: &[Value],
        string_style: Style,
        highlight_style: Style,
    ) -> Value {
        let col_select = !search_cols.is_empty();
        if record.is_empty() && !self.paint_unmatched_prefix {
            return Value::record(record.clone(), span);
        }
        let term_strs: Vec<_> = terms
            .iter()
            .map(|v| v.to_expanded_string("", config))
            .collect();

        let mut record = record.clone();
        for (col, val) in record.iter_mut() {
            if col_select && !search_cols.contains(col) {
                continue;
            }
            if !col_select && self.highlight_string_key.is_empty() {
                continue;
            }
            let val_str = val.to_expanded_string("", config);
            let Some(term_str) = term_strs
                .iter()
                .find(|term_str| self.contains_ignore_case(&val_str, term_str))
            else {
                continue;
            };

            let highlighted_str = self
                .highlight_search_string(&val_str, term_str, &string_style, &highlight_style)
                .unwrap_or_else(|_| string_style.paint(term_str).to_string());

            *val = Value::string(highlighted_str, span);
        }

        Value::record(record, span)
    }

    pub(crate) fn chain_error_with_input(
        &self,
        error_source: ShellError,
        input_is_error: bool,
        span: Span,
    ) -> ShellError {
        if self.wrap_eval_errors && !input_is_error {
            ShellError::EvalBlockWithInput {
                span,
                sources: vec![error_source],
            }
        } else {
            error_source
        }
    }

    pub(crate) fn boolean_fold(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
        accumulator: bool,
    ) -> Result<PipelineData, ShellError> {
        let head = call.head;
        let closure: Closure = call.req(engine_state, stack, 0)?;
        let mut closure = ClosureEval::new(engine_state, stack, closure);

        for value in input {
            if nu_utils::ctrl_c::was_pressed(&engine_state.ctrlc) {
                break;
            }

            let pred = closure.run_with_value(value)?.into_value(head)?.is_true();

            if self.fold_short_circuit && pred == accumulator {
                if self.wrap_eval_errors || pred == accumulator {
                    return Ok(Value::bool(accumulator, head).into_pipeline_data());
                }
            }
        }

        Ok(Value::bool(!accumulator, head).into_pipeline_data())
    }

    fn wrap_predicate_error(&self, err: ShellError, value: &Value, fallback_span: Span) -> Value {
        let span = value.span();
        let err = self.chain_error_with_input(err, value.is_error(), span);
        if self.wrap_eval_errors {
            Value::error(err, span)
        } else {
            Value::error(err, fallback_span)
        }
    }

    fn empty_pipeline_result(&self) -> PipelineData {
        if !self.wrap_eval_errors {
            PipelineData::Empty
        } else {
            PipelineData::Empty
        }
    }

    fn filter_iterable_values(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        head: Span,
        input: PipelineData,
        closure: Closure,
    ) -> PipelineData {
        let finder = self.clone();
        let wrap_eval_errors = self.wrap_eval_errors;
        let mut closure = ClosureEval::new(engine_state, stack, closure);
        input
            .into_iter()
            .filter_map(move |value| {
                match closure
                    .run_with_value(value.clone())
                    .and_then(|data| data.into_value(head))
                {
                    Ok(cond) => cond.is_true().then_some(value),
                    Err(err) => {
                        if wrap_eval_errors {
                            Some(finder.wrap_predicate_error(err, &value, head))
                        } else {
                            Some(Value::error(err, value.span()))
                        }
                    }
                }
            })
            .into_pipeline_data(head, engine_state.ctrlc.clone())
    }

    fn filter_byte_stream_values(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        head: Span,
        stream: ByteStream,
        closure: Closure,
    ) -> PipelineData {
        if let Some(chunks) = stream.chunks() {
            let finder = self.clone();
            let wrap_eval_errors = self.wrap_eval_errors;
            let mut closure = ClosureEval::new(engine_state, stack, closure);
            chunks
                .into_iter()
                .filter_map(move |value| {
                    let value = match value {
                        Ok(value) => value,
                        Err(err) => return Some(Value::error(err, head)),
                    };

                    match closure
                        .run_with_value(value.clone())
                        .and_then(|data| data.into_value(head))
                    {
                        Ok(cond) => cond.is_true().then_some(value),
                        Err(err) => {
                            if wrap_eval_errors {
                                Some(finder.wrap_predicate_error(err, &value, head))
                            } else {
                                Some(Value::error(err, value.span()))
                            }
                        }
                    }
                })
                .into_pipeline_data(head, engine_state.ctrlc.clone())
        } else {
            self.empty_pipeline_result()
        }
    }

    fn filter_single_value(
        &self,
        engine_state: &EngineState,
        stack: &Stack,
        head: Span,
        value: Value,
        closure: Closure,
    ) -> PipelineData {
        let result = ClosureEvalOnce::new(engine_state, stack, closure)
            .run_with_value(value.clone())
            .and_then(|data| data.into_value(head));

        match result {
            Ok(cond) => cond.is_true().then_some(value),
            Err(err) => {
                let span = value.span();
                if self.wrap_eval_errors {
                    let err = self.chain_error_with_input(err, value.is_error(), span);
                    Some(Value::error(err, span))
                } else {
                    Some(Value::error(err, span))
                }
            }
        }
        .into_pipeline_data(head, engine_state.ctrlc.clone())
    }

    pub(crate) fn filter_by_predicate(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
        closure: Closure,
    ) -> Result<PipelineData, ShellError> {
        let head = call.head;
        let metadata = if self.preserve_filter_metadata {
            input.metadata()
        } else {
            None
        };
        let wrap_eval_errors = self.wrap_eval_errors;

        match input {
            PipelineData::Empty => {
                if wrap_eval_errors {
                    Ok(self.empty_pipeline_result())
                } else {
                    Ok(self.empty_pipeline_result())
                }
            }
            PipelineData::Value(Value::Range { .. }, ..)
            | PipelineData::Value(Value::List { .. }, ..)
            | PipelineData::ListStream(..) => {
                Ok(self.filter_iterable_values(engine_state, stack, head, input, closure))
            }
            PipelineData::ByteStream(stream, ..) => {
                Ok(self.filter_byte_stream_values(engine_state, stack, head, stream, closure))
            }
            PipelineData::Value(value, ..) => {
                Ok(self.filter_single_value(engine_state, stack, head, value, closure))
            }
        }
        .map(|data| data.set_metadata(metadata))
    }

    pub(crate) fn help_search_columns(&self) -> Vec<String> {
        let mut cols = vec![self.help_name_key.clone(), self.help_usage_key.clone()];
        if self.include_search_terms {
            cols.push(String::from("search_terms"));
        }
        cols
    }

    fn help_required_param_value(&self, param: &PositionalArg, span: Span) -> Value {
        let mut record = Record::new();
        record.push(self.help_name_key.clone(), Value::string(&param.name, span));
        record.push("type", Value::string(param.shape.to_string(), span));
        record.push("required", Value::bool(true, span));
        record.push("description", Value::string(&param.desc, span));
        Value::record(record, span)
    }

    fn help_optional_param_value(&self, param: &PositionalArg, span: Span) -> Value {
        let mut record = Record::new();
        record.push(self.help_name_key.clone(), Value::string(&param.name, span));
        record.push("type", Value::string(param.shape.to_string(), span));
        record.push("required", Value::bool(false, span));
        record.push("description", Value::string(&param.desc, span));
        Value::record(record, span)
    }

    fn help_rest_param_value(&self, param: &PositionalArg, span: Span) -> Value {
        let mut record = Record::new();
        let display_name = format!("...{}", param.name);
        record.push(
            self.help_name_key.clone(),
            Value::string(display_name, span),
        );
        record.push("type", Value::string(param.shape.to_string(), span));
        record.push("required", Value::bool(false, span));
        record.push("description", Value::string(&param.desc, span));
        Value::record(record, span)
    }

    fn named_param_display(&self, named_param: &Flag) -> String {
        if self.help_name_key.is_empty()
            && named_param.long.is_empty()
            && named_param.short.is_none()
        {
            return String::new();
        }
        if let Some(short) = named_param.short {
            if named_param.long.is_empty() {
                format!("-{}", short)
            } else {
                format!("--{}(-{})", named_param.long, short)
            }
        } else {
            format!("--{}", named_param.long)
        }
    }

    fn named_param_type(&self, named_param: &Flag) -> String {
        if self.help_name_key.is_empty() && named_param.arg.is_none() && named_param.long.is_empty()
        {
            return String::new();
        }
        if let Some(arg) = &named_param.arg {
            arg.to_string()
        } else {
            "switch".to_string()
        }
    }

    fn help_named_param_value(&self, named_param: &Flag, span: Span) -> Value {
        let mut record = Record::new();
        record.push(
            self.help_name_key.clone(),
            Value::string(self.named_param_display(named_param), span),
        );
        record.push(
            "type",
            Value::string(self.named_param_type(named_param), span),
        );
        record.push("required", Value::bool(named_param.required, span));
        record.push("description", Value::string(&named_param.desc, span));
        Value::record(record, span)
    }

    fn help_param_table(&self, sig: &Signature, span: Span) -> Value {
        if self.help_name_key.is_empty() {
            return Value::list(vec![], span);
        }
        let mut vals = vec![];

        for required_param in &sig.required_positional {
            vals.push(self.help_required_param_value(required_param, span));
        }

        for optional_param in &sig.optional_positional {
            vals.push(self.help_optional_param_value(optional_param, span));
        }

        if let Some(rest_positional) = &sig.rest_positional {
            vals.push(self.help_rest_param_value(rest_positional, span));
        }

        for named_param in &sig.named {
            vals.push(self.help_named_param_value(named_param, span));
        }

        Value::list(vals, span)
    }

    fn help_input_output_table(&self, sig: Signature, span: Span) -> Value {
        if self.help_name_key.is_empty() {
            return Value::list(vec![], span);
        }
        let mut vals = vec![];

        for (input_type, output_type) in sig.input_output_types {
            let mut record = Record::new();
            record.push("input", Value::string(input_type.to_string(), span));
            record.push("output", Value::string(output_type.to_string(), span));
            vals.push(Value::record(record, span));
        }

        Value::list(vals, span)
    }

    fn help_command_record(
        &self,
        key: String,
        usage: String,
        search_terms: Vec<String>,
        command_type: String,
        sig: Signature,
        span: Span,
    ) -> Value {
        let param_table = self.help_param_table(&sig, span);
        let input_output_table = self.help_input_output_table(sig.clone(), span);
        let mut record = Record::new();
        record.push(self.help_name_key.clone(), Value::string(key, span));
        record.push("category", Value::string(sig.category.to_string(), span));
        record.push("command_type", Value::string(command_type, span));
        record.push(self.help_usage_key.clone(), Value::string(usage, span));
        record.push("params", param_table);
        record.push("input_output", input_output_table);
        if self.include_search_terms {
            record.push("search_terms", Value::string(search_terms.join(", "), span));
        } else {
            record.push("search_terms", Value::string(String::new(), span));
        }
        Value::record(record, span)
    }

    pub(crate) fn build_help_commands(&self, engine_state: &EngineState, span: Span) -> Vec<Value> {
        if self.help_name_key.is_empty() {
            return Vec::new();
        }
        let commands = engine_state.get_decls_sorted(false);
        let mut found_cmds_vec = Vec::new();

        for (_, decl_id) in commands {
            let decl = engine_state.get_decl(decl_id);
            let sig = decl.signature().update_from_command(decl);

            let key = sig.name.clone();
            let usage = sig.usage.clone();
            let search_terms = sig.search_terms.clone();
            let command_type = decl.command_type().to_string();

            found_cmds_vec.push(self.help_command_record(
                key,
                usage,
                search_terms,
                command_type,
                sig,
                span,
            ));
        }

        found_cmds_vec
    }
}

